/** Link-preview images, generated by `yarn generate-promo` from src/app/promo/<slug> into
 * public/thumbnails/<slug>.png. Dependency-free so the generator script can import it too. */

/** 1200x630 is the 1.91:1 ratio social platforms crop link previews to. */
export const THUMBNAIL_WIDTH = 1200;
export const THUMBNAIL_HEIGHT = 630;
/** Folder under public/ that holds the generated images. */
export const THUMBNAIL_FOLDER = "thumbnails";

export interface Thumbnail {
  slug: string;
  alt: string;
}

export function thumbnailUrl(slug: string): string {
  return `/${THUMBNAIL_FOLDER}/${slug}.png`;
}

/** The `openGraph` and `twitter` image fields for a page's thumbnail, to merge into its metadata. */
export function thumbnailImages({ slug, alt }: Thumbnail) {
  return {
    openGraph: {
      images: [{ url: thumbnailUrl(slug), width: THUMBNAIL_WIDTH, height: THUMBNAIL_HEIGHT, alt }],
    },
    twitter: { images: [thumbnailUrl(slug)] },
  };
}
